<?php
namespace App\Models;use Illuminate\Database\Eloquent\Concerns\HasUuids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany,HasOne};
final class Policy extends Model{use HasUuids;protected$fillable=['tenant_id','proposal_id','payment_intent_id','carrier_id','party_id','policy_number','certificate_number','status','coverage_starts_at','coverage_ends_at','terms_snapshot','version','currency','premium_minor','issued_at','issuance_reference','issuance_request_id','previous_policy_id','terms_hash'];protected function casts():array{return['coverage_starts_at'=>'datetime','coverage_ends_at'=>'datetime','terms_snapshot'=>'array','issued_at'=>'datetime'];}public function tenant():BelongsTo{return$this->belongsTo(Tenant::class);}public function party():BelongsTo{return$this->belongsTo(Party::class);}public function carrier():BelongsTo{return$this->belongsTo(Carrier::class);}public function proposal():BelongsTo{return$this->belongsTo(Proposal::class);}public function transactions():HasMany{return$this->hasMany(PolicyTransaction::class);}public function certificates():HasMany{return$this->hasMany(PolicyCertificate::class);}public function renewals():HasMany{return$this->hasMany(RenewalCase::class);}public function fulfilmentOrder():HasOne{return$this->hasOne(FulfilmentOrder::class);}}
